  function wrap(ctx,value,x,y,width,lineHeight,maxLines){var words=txt(value).split(/\s+/),line='',lines=[];words.forEach(function(word){var test=line?line+' '+word:word;if(ctx.measureText(test).width>width&&line){lines.push(line);line=word}else line=test});if(line)lines.push(line);lines.slice(0,maxLines||99).forEach(function(v,i){ctx.fillText(v,x,y+i*lineHeight)});return Math.min(lines.length,maxLines||99)*lineHeight}
  function reportCanvas(title,meta,headers,rows,footer){var c=doc.createElement('canvas');c.width=1240;c.height=1754;var x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.fillStyle='#0b392f';x.fillRect(0,0,c.width,165);x.fillStyle='#fff';x.font='700 50px "Malgun Gothic",sans-serif';x.fillText(title,60,85);x.font='25px "Malgun Gothic",sans-serif';x.fillText(meta,60,132);var y=220,cols=headers.length,w=(c.width-120)/cols;x.font='700 23px "Malgun Gothic",sans-serif';x.textAlign='center';x.fillStyle='#e6f1ee';x.fillRect(60,y,c.width-120,60);x.fillStyle='#102a27';headers.forEach(function(h,i){x.fillText(h,60+i*w+w/2,y+38)});y+=60;x.font='21px "Malgun Gothic",sans-serif';rows.forEach(function(row){if(y>1590)return;x.strokeStyle='#d5dfdc';x.strokeRect(60,y,c.width-120,62);row.forEach(function(v,i){wrap(x,v,60+i*w+8,y+25,w-16,22,2)});y+=62});x.textAlign='left';x.fillStyle='#52645f';x.font='24px "Malgun Gothic",sans-serif';wrap(x,footer||'',60,1660,c.width-120,30,2);return c}
