  function ensurePcShareStyle(){if(doc.getElementById('mesPcShareStyle'))return;var style=doc.createElement('style');style.id='mesPcShareStyle';style.textContent='.mes-pc-share-overlay{position:fixed;inset:0;z-index:100000;background:rgba(5,31,27,.64);display:grid;place-items:center;padding:24px}.mes-pc-share-card{box-sizing:border-box;width:min(720px,96vw);max-height:90vh;overflow:auto;background:#fff;border-radius:22px;padding:24px;box-shadow:0 24px 70px rgba(0,0,0,.28)}.mes-pc-share-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.mes-pc-share-head small{color:#08735f;font-weight:900}.mes-pc-share-head h2{margin:5px 0 0}.mes-pc-share-guide{padding:14px;border-radius:12px;background:#e8f7f2;font-weight:800}.mes-pc-share-text{box-sizing:border-box;width:100%;min-height:260px;padding:14px;border:1px solid #b8cbc5;border-radius:12px;white-space:pre-wrap;font:15px/1.55 "Malgun Gothic",sans-serif}@media(max-width:760px){.mes-pc-share-overlay{padding:10px}.mes-pc-share-card{padding:16px}.mes-pc-share-text{min-height:220px}}';doc.head.appendChild(style)}
