  async function shareBlob(blob,name,title,textValue){var file=new File([blob],name,{type:'application/pdf'}),fileShare=!!(mobileShareAvailable()&&navigator.canShare&&navigator.canShare({files:[file]}));if(fileShare){try{await navigator.share({title:title,text:textValue,files:[file]});return}catch(error){if(error&&error.name==='AbortError')return;downloadBlob(blob,name);var copied=await copyShareText(textValue);showPcShareDialog(title,textValue,copied);notify('이 기기에서는 PDF 직접 전송이 제한되어 파일을 내려받았습니다.');return}}downloadBlob(blob,name);if(mobileShareAvailable()){try{await navigator.share({title:title,text:textValue});notify('PDF를 내려받았습니다. 카카오톡에서 파일을 첨부하세요.');return}catch(error){if(error&&error.name==='AbortError')return}}var copied=await copyShareText(textValue);showPcShareDialog(title,textValue,copied);notify('PDF를 내려받았습니다.'+(copied?' 공유문구도 복사했습니다.':' 카카오톡 파일첨부에서 선택하세요.'))}

