  window.updatePreSettlementGroup=function(target){var article=target&&target.closest?target.closest('.pre-settle-row'):target;if(!article)return;var total=Array.from(article.querySelectorAll('[name=preWeight]')).reduce(function(sum,input){return sum+n(input.value)},0),available=n(article.dataset.sourceWeight),remaining=available-total,summary=article.querySelector('.pre-settle-weight-summary');if(summary){summary.textContent='입력 합계 '+fmt(total)+' kg / 남은 중량 '+fmt(Math.max(0,remaining))+' kg';summary.classList.toggle('over',remaining<-.0001)}article.classList.toggle('weight-over',remaining<-.0001)};
  window.addPreSettlementLine=function(button){var article=button.closest('.pre-settle-row'),holder=article.querySelector('.pre-settle-splits'),first=holder.querySelector('.pre-settle-split'),seed={mainGrade:first&&first.querySelector('[name=preMain]').value||article.dataset.sourceGrade||'',subGrade:first&&first.querySelector('[name=preSub]').value||article.dataset.sourceSub||'',weight:''};holder.insertAdjacentHTML('beforeend',preSettlementLine(seed,holder.children.length));article.querySelector('[name=selected]').checked=true;updatePreSettlementGroup(article);var added=holder.lastElementChild;added.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(function(){added.querySelector('[name=preMain]')?.focus()},250)};
