  window.openPreSettlement=function(poNo){var saved=preRecords(poNo),source=preSourceRows(poNo);$('modalTitle').textContent=poNo+' · 선세틀 강종변환';$('modalBody').innerHTML='<form onsubmit="savePreSettlement(event,this,decodeURIComponent(\''+encodeURIComponent(poNo)+'\'))"><p>사내입고번호별로 변환행을 여러 개 추가할 수 있습니다. 입력 중량 합계는 원 중량을 넘을 수 없습니다.</p><div class="pre-settle-list">'+source.map(function(row,i){var olds=saved.filter(function(s){return txt(s.sourceId)===txt(row.id)});if(!olds.length)olds=[{mainGrade:rowGrade(row),subGrade:rowSub(row),weight:row.weight}];var selected=saved.some(function(s){return txt(s.sourceId)===txt(row.id)});return'<article class="pre-settle-row" data-source-id="'+html(row.id)+'" data-source-weight="'+html(row.weight)+'" data-source-grade="'+html(rowGrade(row))+'" data-source-sub="'+html(rowSub(row))+'"><label class="pre-check"><input type="checkbox" name="selected" value="'+html(row.id)+'" '+(selected?'checked':'')+'> 사내입고번호 '+html(row.packageNo||('행 '+(i+1)))+' · 거래처강종 '+html(rowGrade(row))+' · 원 중량 '+fmt(row.weight)+' kg</label><div class="pre-settle-splits">'+olds.map(function(old,index){return preSettlementLine(old,index)}).join('')+'</div><div class="pre-settle-group-actions"><button type="button" class="btn" onclick="addPreSettlementLine(this)">+ 이 사내입고번호에 행 추가</button><strong class="pre-settle-weight-summary"></strong></div></article>'}).join('')+'</div><div class="actions"><button class="btn primary">선세틀 저장</button><button type="button" class="btn" onclick="closeModal()">취소</button></div></form>';$('modal').classList.add('on');Array.from($('modalBody').querySelectorAll('.pre-settle-row')).forEach(updatePreSettlementGroup)};
  window.savePreSettlement=async function(event,form,poNo){event.preventDefault();var source=preSourceRows(poNo),stamp=new Date().toISOString(),articles=Array.from(form.querySelectorAll('.pre-settle-row')).filter(function(article){return article.querySelector('[name=selected]').checked});if(!articles.length)return notify('선세틀할 사내입고번호를 선택하세요.',true);var records=[];for(var a=0;a<articles.length;a++){var article=articles[a],sourceId=article.dataset.sourceId,row=source.find(function(s){return txt(s.id)===txt(sourceId)}),lines=Array.from(article.querySelectorAll('.pre-settle-split')),total=lines.reduce(function(sum,line){return sum+n(line.querySelector('[name=preWeight]').value)},0),available=n(row&&row.weight);if(total>available+.0001){article.scrollIntoView({behavior:'smooth',block:'center'});article.querySelector('[name=preWeight]')?.focus();return notify((row&&row.packageNo||'사내입고번호')+'의 입력 합계가 원 중량을 초과했습니다.',true)}for(var b=0;b<lines.length;b++){var line=lines[b],record={id:line.dataset.recordId||id(),poNo:poNo,sourceId:sourceId,packageNo:row&&row.packageNo||'',sourceGrade:rowGrade(row||{}),mainGrade:txt(line.querySelector('[name=preMain]').value),subGrade:txt(line.querySelector('[name=preSub]').value),weight:n(line.querySelector('[name=preWeight]').value),status:'COMPLETE',operatorName:userName(),createdAt:stamp};if(!record.mainGrade||!record.subGrade||record.weight<=0){line.scrollIntoView({behavior:'smooth',block:'center'});(!record.mainGrade?line.querySelector('[name=preMain]'):!record.subGrade?line.querySelector('[name=preSub]'):line.querySelector('[name=preWeight]'))?.focus();return notify('모든 변환행의 최종강종·소강종·중량을 입력하세요.',true)}records.push(record)}}var ok=await commit('선세틀 저장',['preSettlements'],function(shared){shared.preSettlements=list(shared.preSettlements).filter(function(r){return txt(r.poNo)!==txt(poNo)}).concat(records)});if(ok){openPreSettlementDetail(poNo)}};
