  window.recalculateOrderAmounts=function(form){if(!form)return;var rateInput=form.querySelector('[name=exchangeRate]'),currencyInput=form.querySelector('[name=currency]'),rate=n(rateInput&&rateInput.value)||1,currency=txt(currencyInput&&currencyInput.value)||'USD';if(currency==='KRW'&&rateInput&&!n(rateInput.value)){rateInput.value='1';rate=1}form.querySelectorAll('[data-order-currency]').forEach(function(node){node.textContent=currency});form.querySelectorAll('.order-create-line').forEach(function(line){var quantity=n(line.querySelector('[name=quantity]')&&line.querySelector('[name=quantity]').value),price=n(line.querySelector('[name=price]')&&line.querySelector('[name=price]').value),amount=quantity*price,krw=amount*rate,amountInput=line.querySelector('[name=amount]'),krwInput=line.querySelector('[name=krwAmount]');if(amountInput)amountInput.value=amount?String(Math.round(amount*100)/100):'';if(krwInput)krwInput.value=krw?String(Math.round(krw*100)/100):''})};
