  function modeChooser(type){var orderLabel=type==='PO'?'P.O':'S.O';$('modalTitle').textContent=orderLabel+' 등록';$('modalBody').innerHTML='<div class="order-mode-grid"><button class="order-mode-card" onclick="openOrderCreate(\''+type+'\')"><b>'+orderLabel+' 생성</b><span>직접 입력하고 원본 양식 미리보기·PDF를 생성합니다.</span></button><button class="order-mode-card" onclick="openOrderDocumentRegistration(\''+type+'\')"><b>'+orderLabel+' 서류로 등록하기</b><span>PDF·Excel·사진을 분석하며 P.O와 S.O가 같은 학습 매칭자료를 공유합니다.</span></button></div>';$('modal').classList.add('on')}
  var baseOpenOrderCreate=window.openOrderCreate;
  window.openOrderCreate=function(type,data){var result=baseOpenOrderCreate.apply(this,arguments),orderLabel=type==='SO'?'S.O':'P.O';$('modalTitle').textContent=orderLabel+' 생성 · 양식 미리보기';var first=$('mesOrderCreateForm')&&$('mesOrderCreateForm').querySelector('input[name=orderNo]');if(first&&first.closest('label'))first.closest('label').childNodes[0].nodeValue=orderLabel+' 번호';var submit=$('mesOrderCreateForm')&&$('mesOrderCreateForm').querySelector('button[type=submit],button:not([type])');if(submit)submit.textContent=orderLabel+' 저장';return result};
