  window.analyzeOrderDocument=async function(type,file){if(!file)return;var statusEl=$('orderImportStatus');if(statusEl)statusEl.textContent='원본문자·페이지 사진·저장자료 비교 분석 중…';$('progress').classList.add('on');try{var importer=window.MesDocumentImporterV4||window.__mesDocumentImporterV4;if(!importer||typeof importer.importFile!=='function')throw Error('공용 서류 분석기를 불러오지 못했습니다.');var d=await importer.importFile(file,{targetType:type}),data={orderNo:type==='PO'?(d.poNo||''):(d.soNo||d.poNo||''),poNo:d.poNo||'',partner:d.company||'',address:d.address||'',tel:d.tel||'',fax:d.fax||'',date:d.contractDate||today(),shipment:d.shipment||'',payment:d.paymentTerm||'',packing:d.packing||'',note:d.note||'',currency:d.currency||'USD',items:list(d.items).map(function(r){var source=[r.marking,r.description].filter(Boolean).filter(function(value,index,array){return array.indexOf(value)===index}).join(' / ');return{productType:r.productType||'',item:type==='PO'?(source||r.matchedMarking||''):(r.marking||''),description:r.matchedMarking||r.description||r.marking||'',quantity:n(r.weight||r.quantity),price:n(r.price||r.unitPrice),amount:n(r.amount)}})};if(!data.items.length)throw Error('품목·중량 행을 찾지 못했습니다.');openOrderCreate(type,data);var diagnostics=d.diagnostics||{},form=$('mesOrderCreateForm'),method=diagnostics.extractionMethod||'문서분석',confidence=n(diagnostics.confidence);if(form){var message=diagnostics.warning||('선택 결과: '+method+' · 신뢰도 '+confidence+'%'+(diagnostics.usedSavedData?' · 저장자료 자동보정':''));form.insertAdjacentHTML('afterbegin','<div class="mes-import-review '+(diagnostics.reviewRequired?'warning':'ok')+'">'+html(message)+'</div>')}notify(file.name+' · '+d.items.length+'개 품목 자동완성 · '+method+(diagnostics.reviewRequired?' · 중량·단가 확인 필요':diagnostics.usedSavedData?' · 저장자료 자동보정 완료':''))}catch(error){if(statusEl)statusEl.textContent='자동완성 실패: '+error.message;notify(type+'.O 서류 자동완성 실패: '+error.message,true)}finally{$('progress').classList.remove('on')}};
