  async function uploadAsset(file,folder){if(!file)return'';var body=file;if(file.type.indexOf('image/')===0){var bitmap=await createImageBitmap(file),scale=Math.min(1,1280/Math.max(bitmap.width,bitmap.height)),c=doc.createElement('canvas');c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);body=await new Promise(function(resolve,reject){c.toBlob(function(b){return b?resolve(b):reject(Error('사진 압축 실패'))},'image/jpeg',.7)});}var ext=file.type==='application/pdf'?'pdf':'jpg',path='mes/'+folder+'/'+Date.now()+'-'+id()+'.'+ext,encoded=path.split('/').map(encodeURIComponent).join('/'),response=await fetch(API+'/storage/v1/object/scrap-photos/'+encoded,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+KEY,'Content-Type':file.type==='application/pdf'?'application/pdf':'image/jpeg','x-upsert':'true'},body:body});if(!response.ok)throw Error('첨부 저장 HTTP '+response.status);return path}
