  function mesShareLink(view,key){
    try{
      var url=new URL(location.href);
      url.searchParams.set('sharedView',txt(view||currentView||'dashboard'));
      if(key)url.searchParams.set('sharedKey',txt(key));
      url.hash=txt(view||currentView||'dashboard');
      return url.href;
    }catch(_){return location.href}
  }
  async function shareText(titleValue,body,linkValue){
    var link=txt(linkValue)||mesShareLink(currentView),full=body+(body.indexOf(link)>=0?'':'\n\n확인 링크:\n'+link),data={title:titleValue,text:body,url:link};
    try{if(mobileShareAvailable()){await navigator.share(data);return true;}}catch(error){if(error&&error.name==='AbortError')return false;}
    var copied=await copyShareText(full);
    showPcShareDialog(titleValue,full,copied);
    notify(copied?'브라우저 공유 기능이 없어 내용과 링크를 복사했습니다.':'공유문구를 자동 복사하지 못했습니다. 다시 눌러 주세요.',!copied);
    return copied;
  }
  window.mesShareText=shareText;
  function stageFormValue(name){var form=$('modalBody')?.querySelector('form'),field=form?.querySelector('[name="'+name+'"]:checked')||form?.querySelector('[name="'+name+'"]');return field?txt(field.value):''}
  function shareGrade(item){return txt(item.customerGrade||item.grade||[item.productType,item.mainGrade,item.subGrade,item.detailGrade].filter(Boolean).join(' · '))||'강종 미지정'}
  function inboundShareItems(st,request){var items=list(request.items);if(items.length)return items;return list(st.pos).filter(function(item){return !item.inboundRequestSuperseded&&(txt(item.inboundRequestId)===txt(request.id)||txt(item.poNo)===txt(request.poNo));})}
