  window.shareStageRecord=function(kind,key){var st=currentState(),body='',targetView='',formContainer=stageFormValue('containerSize');if(kind.indexOf('입고')===0){targetView='inboundRequest';var r=list(st.purchaseRequests).find(function(x){return x.id===key||x.requestNo===key||x.poNo===key})||{},items=inboundShareItems(st,r),arrivalDate=stageFormValue('arrivalPlanDate')||r.arrivalPlanDate||r.expectedArrivalDate||'-',requestDate=stageFormValue('requestDate')||r.requestDate||'-',confirmedDate=stageFormValue('confirmedDate')||r.confirmedInboundDate||'-',confirmedTime=stageFormValue('confirmedTime')||r.confirmedInboundTime||'-',container=formContainer||r.containerSize||r.inboundContainerSize||'-',vehicle=stageFormValue('vehicleNo')||r.vehicleNo||'기입요망',contact=stageFormValue('contact')||r.contact||'기입요망',totalGw=items.reduce(function(sum,item){return sum+n(item.gw||item.grossWeight||item.weight)},0),totalNw=items.reduce(function(sum,item){return sum+n(item.nw||item.netWeight||item.weight)},0);body='[신성금속 '+kind+']\nP.O: '+(r.poNo||'-')+'\n입고요청번호: '+(r.requestNo||'-')+'\n거래처: '+(r.company||'-')+'\n입항예정일: '+arrivalDate+'\n입고요청일: '+requestDate;if(kind.indexOf('확정')>=0)body+='\n입고확정일: '+confirmedDate+'\n입고확정시간: '+confirmedTime;body+='\n컨테이너: '+container+'\n차량번호: '+vehicle+'\n연락처: '+contact+'\n패키지: '+items.length+'개\n\n[강종·패키지 내역]\n'+inboundItemLines(items)+'\n\n전체 G/W: '+fmt(totalGw)+' kg\n전체 N/W: '+fmt(totalNw)+' kg\n작업자: '+(r.confirmOperatorName||r.requestOperatorName||userName()||'-')}else{targetView='shippingPlan';var rows=list(st.salesOrders).filter(function(x){return txt(x.soNo)===txt(key)}),s=rows[0]||{},planDate=s.shippingPlanDate||s.shipDate||'-',requestDate=stageFormValue('requestDate')||s.shippingRequestDate||'-',confirmedDate=stageFormValue('confirmedDate')||s.shippingConfirmedDate||'-',confirmedTime=stageFormValue('confirmedTime')||s.shippingConfirmedTime||'-',container=formContainer||s.shippingContainerSize||s.containerSize||'-',containerNo=stageFormValue('containerNo')||s.shippingContainerNo||s.containerNo||'기입요망',sealNo=stageFormValue('sealNo')||s.shippingSealNo||s.sealNo||'기입요망',vehicle=stageFormValue('vehicleNo')||s.shippingVehicleNo||s.vehicleNo||'기입요망',contact=stageFormValue('contact')||s.driverPhone||s.contact||'기입요망',total=rows.reduce(function(sum,item){return sum+n(item.weight||item.nw||item.quantity)},0);body='[신성금속 '+kind+']\nS.O: '+(key||'-')+'\n판매처: '+(s.customer||'-')+'\n출하요청일: '+planDate+'\n배차요청일: '+requestDate;if(kind.indexOf('상차')>=0)body+='\n상차예정일: '+confirmedDate+'\n상차예정시간: '+confirmedTime+'\n컨테이너 번호: '+containerNo+'\n실번호: '+sealNo;body+='\n컨테이너 규격: '+container+'\n차량번호: '+vehicle+'\n연락처: '+contact+'\n\n[강종·중량 내역]\n'+shippingItemLines(rows)+'\n\n전체 중량: '+fmt(total)+' kg\n작업자: '+(s.shippingConfirmOperatorName||s.shippingRequestOperatorName||userName()||'-')}return shareText('신성금속 '+kind,body,mesShareLink(targetView,key))};
